"""Publish bounded coverage findings and current physical-scale comparisons."""
from pathlib import Path
import ast,hashlib,json,shutil,subprocess
R=Path(__file__).resolve().parents[1];D=R/'character/bill-installed-coverage-2026-10-04';O=R/'output/bill-installed-coverage-v2'
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();q=json.loads((D/'source-audit.json').read_text());review=json.loads((D/'review.json').read_text());v=json.loads((O/'validation.json').read_text());assert v['passed'] and v['checks']==11974
assert all(sha(R/p)==h for p,h in review['frozenInputs'].items())
required={}
for gear in ['bare','helmet']:
 keys={r['action']+'-'+r['direction'] for r in q['lifeRows'] if r['gear']==gear and not r['action'].startswith('bunk-')}
 keys.update(a+'-'+d for a in ['idle','walk','run','interact','kneel','repair','stand','carry','carry-start','pickup','unload','weld','swim','tread'] for d in ['east','south','west','north'])
 keys.update('carry-turn-'+a+'-'+b for a in ['east','south','west','north'] for b in ['east','south','west','north'] if a!=b)
 keys.update(a+'-east' for a in ['bunk-enter','bunk-sleep','bunk-exit'])
 missing=sorted(keys-q['selected'][gear].keys());assert not missing,(gear,missing)
 required[gear]={'checkedKeys':len(keys),'missing':missing}
findings={'east':'Installed bare idle/walk/run/reach/carry/weld share stronger master identity and matte finish. Retained kneel/repair/stand are darker and smoother; swim differs in face/light. No new repair or universal sequence acceptance in this audit.','west':'Highest remaining source consistency priority: selected dry heads and suit are darker/softer than original registered master; swim is noticeably brighter. Previous 48-phase study remains provisional and unselected; rejected trials stay rejected.','south':'Recognizable frontal identity, with smoother running cloth and face angle/shading changes in interaction, carrying and welding.','north':'Rear layout broadly coherent against prepared stance reference; running/welding quilt detail differs. Prepared reference is not the untouched original rear master.'}
review.update(visualReview='All eight refreshed current bare/equipped cardinal boards actually inspected.',findings=findings,nativeSourceValidation=v,requiredActionCoverage=required,fullVisualAcceptance=False,sourceCoverageCompleteWithinExplicitKeys=True)
(D/'review.json').write_text(json.dumps(review,indent=2)+'\n')
for name in ['validation.json','report.json','inputs-before.json','inputs-after.json']:shutil.copy2(O/name,D/('native-'+name))
lines=['# Bill installed coverage — October 4, 2026','','Current normal loader: **216 bare states / 198 helmet states; 3,576 frame slots.**','', '11,974 checks passed for actual materialized source pixels, clocks and density. This is a source audit; native jobs and Continue have their separate installation evidence.','', '| Set | States | Frame slots |','|---|---:|---:|','| Bare | 216 | 1,860 |','| Helmet | 198 | 1,716 |','',f"Explicit ordinary/life/cargo/turn/water checks: {required['bare']['checkedKeys']} keys per gear, zero missing.",'','The 18 absent bunk combinations in an all-direction table are intentional: `scripts/major_bill_npc.gd` forces East for the special bunk. Generic lie/sleep/get-up still exist in every direction. Helmet eat/drink presents inspection with the sealed helmet, as selected by `scripts/crew_life.gd`. These are not requests for new art.','','## Installation and visual scope','','The reviewed bare East family and shared turn poses are installed. Existing equipment, life and water banks retain their selections. No runtime or artwork changed in this audit. Historical manifests and executable builds were not rewritten.','','## Remaining visual work','']+[f'- **{direction.title()}:** {finding}' for direction,finding in findings.items()]
lines+=['','Next: bounded West master consistency work; inspect the existing study before authoring again, preserve rejected trials and accepted East work. Do not call the full master-matching objective complete from coverage alone. All-route motion review and a release were not performed.','', '[Installed East native jobs and Continue](../bill-master-install-v1/index.html)']
(D/'REVIEW.md').write_text('\n'.join(lines)+'\n')
html='''<!doctype html><meta charset="utf-8"><title>Bill — installed coverage</title><style>body{background:#1f2328;color:#eee;font:18px system-ui;margin:24px auto;max-width:1300px}img{max-width:100%}a{color:#9cdae4}.summary{background:#273a43;padding:20px}li{margin:12px 0}</style><h1>Bill: installed coverage and remaining polish</h1><div class="summary"><b>216 bare + 198 helmet states · 3,576 selected frames</b><p>11,974 source, clock and density checks passed. No missing keys in the explicit everyday, cargo, turn and basic water coverage list. East-only bunk views are deliberate.</p></div><p>The repaired bare East family is installed and has construction, cargo and Continue evidence. Full master-style consistency remains open: West is the clearest remaining priority.</p><p><a href="../bill-master-install-v1/">Installed East review</a> · <a href="REVIEW.md">Coverage and remaining work</a></p><ul>'''
html+=''.join(f'<li><b>{d.title()}:</b> {f}</li>' for d,f in findings.items())+'</ul><p>Representative whole poses at the same physical scale, with diagnostic head crops. Bare master references do not establish helmet design acceptance. North uses a prepared rear stance reference. These are static comparisons, not continuous motion proof.</p>'
for direction in ['east','west','south','north']:
 for gear in ['bare','helmet']:html+=f'<h2>{direction.title()} · {gear}</h2><img src="{gear}-{direction}.png" alt="Current {gear} {direction} comparison">'
(D/'index.html').write_text(html,encoding='utf-8')
names=['audit_bill_installed_coverage_v1.py','run_bill_installed_coverage_v1.py','prepare_bill_installed_coverage_v2.py','run_bill_installed_coverage_v2.py','prepare_bill_installed_family_review_v1.py','publish_bill_installed_coverage_v1.py']
for name in names:ast.parse((R/'tools'/name).read_text())
ast.parse((D/'build_review.py').read_text())
for version in ['v1','v2']:
 uid=(R/f'tools/review_bill_installed_coverage_{version}.gd.uid').read_text().strip();assert sum(p.read_text().strip()==uid for p in (R/'tools').glob('*.gd.uid'))==1
pngs=[p.relative_to(R).as_posix() for p in D.glob('*.png')];result=subprocess.run(['git','check-attr','-z','--stdin','filter'],input=('\0'.join(pngs)+'\0').encode(),capture_output=True,check=True,cwd=R);items=result.stdout.decode().split('\0');assert all(items[i+2]=='lfs' for i in range(0,len(items)-1,3))
print(json.dumps({'states':q['stateCounts'],'frames':sum(q['selectedSlots'].values()),'required':required,'checks':v['checks'],'pythonSyntax':7,'pairedUIDs':2,'pngLFS':len(pngs),'runtimeOrArtChanges':False}))
